script:
function getValue(name) {
  return document.getElementById(name)?.value.trim() || "";
}

async function handleOnboardingSubmit(container) {
  const submitBtn = document.getElementById("submit-btn");

  const inputs = container.querySelectorAll("input[required]");
  for (const input of inputs) {
    if (!input.value.trim()) {
      toast.error("Please fill all required fields");
      input.focus();
      return;
    }
  }

  const data = {
    firstName: getValue("first-name"),
    lastName: getValue("last-name"),
    company: getValue("company-name"),
    designation: getValue("designation"),
    handle: getValue("handle").toLowerCase(),
    bio: getValue("bio"),
  };

  const user = page_data?.user;
  if (!user) {
    window.location.href =
      "/login?redirect-to=" + encodeURIComponent(window.location.pathname);
    return;
  }

  if (submitBtn) submitBtn.setAttribute("disabled", "true");

  try {
    // Set name on the User record.
    await frappeClient.setValue("User", user, {
      first_name: data.firstName,
      last_name: data.lastName,
    });

    // Create the Cafe User profile (autonamed by the user field).
    await frappeClient.post("Cafe User", {
      user,
      handle: data.handle,
      company: data.company,
      designation: data.designation,
      bio: data.bio,
    });

    toast.success("Profile created successfully");
    window.location.href = `/cafe/profile/${data.handle}`;
  } catch (error) {
    console.error(error);
    toast.error(error.message || "Failed to create profile");
    if (submitBtn) submitBtn.removeAttribute("disabled");
  }
}

function init() {
  const container = document.getElementById("onboarding-form");
  const submitBtn = document.getElementById("submit-btn");
  if (!container || !submitBtn) return;

  submitBtn.addEventListener("click", (e) => {
    e.preventDefault();
    e.stopPropagation();
    handleOnboardingSubmit(container);
  });

  // Allow Enter in any input to submit.
  container.addEventListener("keydown", (e) => {
    if (e.key === "Enter" && e.target.tagName === "INPUT") {
      e.preventDefault();
      handleOnboardingSubmit(container);
    }
  });
}

if (document.readyState === "loading") {
  document.addEventListener("DOMContentLoaded", init);
} else {
  init();
}
